use std::sync::OnceLock;

static SEQS: OnceLock<Vec<(String, String)>> = OnceLock::new();

pub fn seqs() -> &'static [(String, String)] {
    SEQS.get_or_init(|| {
        RAW_SEQS
            .iter()
            .map(|&(id, sequence)| (id.to_owned(), sequence.to_owned()))
            .collect()
    })
}

