#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn bundled_corpus_has_complete_unique_proteins() {
        let records = seqs();
        assert_eq!(records.len(), 389);
        assert_eq!(records.first().unwrap().0, "d2dc3a_");
        assert!(records
            .first()
            .unwrap()
            .1
            .starts_with("eelseaerkavqamwarly"));
        assert!(records.iter().all(|(id, sequence)| !id.is_empty()
            && !sequence.is_empty()
            && sequence.bytes().all(|c| c.is_ascii_alphabetic())));
        let unique: std::collections::HashSet<_> = records.iter().map(|(id, _)| id).collect();
        assert_eq!(unique.len(), records.len());
    }
}
